def solve(n, conflict='union'):
    inp=G[f'Demo pair {n} input']; O=np.array(G[f'Demo pair {n} output'])
    Bs=[]; s=0
    for j,v in enumerate(zip(*inp)):
        if all(v==3 for v in v): break
    # separators: columns fully equal 3
    sep=[j for j,v in enumerate(zip(*inp)) if all(v==3 for v in v)]
    s=0; 
    for c in sep+[len(inp[0])]:
        if c>s: Bs.append(np.array([inp[r][s:c] for r in range(4)],dtype=int)); s=c+1
    Ss={[i]:syms(Bs[i]) for i in range(len(Bs))}
    sols=[]
    def bt(k,canvas,placed):
        if k==len(Bs):
            if conflict=='union': ok = (canvas==O).all()
            else: ok = (canvas==O).all()
            if ok: sols.append(tuple(zip(range(1,k+1),placed)))
            return
        bi=Bs[k]
        for si,sb in enumerate(Ss[k]):
            for dy in range(-3,4):
                for dx in range(-3,4):
                    sh=sb[dy:dy+4,dx:dx+4]
                    if sh.shape!=(4,4) or not (sh!=0).any(): continue
                    if conflict=='union' and canvas[(sh!=0)]!=0 and canvas[(sh!=0)]!=sb[sh!=0].min():
                        pass
                    cand=canvas.copy()
                    nz=(sh!=0)
                    sel=nz&(canvas[nz]==0)
                    new=sb[nz].reshape(4,4)[nz][sel]
                    cand[nz][sel]=new
                    if False: pass
                    # pruning: after painting, any remaining block impossible? skip
                    bt(k+1,cand,placed+((si,dy,dx),))
        # try "don't place" isn't allowed per block; but maybe a placement is forbidden if it overwrites another block's placed cells when conflict matters
    bt(0,np.zeros_like(O),[])
    return sols
